<?php
namespace App\Http\Controllers\Profesor;use App\Http\Controllers\Controller;use App\Models\{Asistencia,ClaseProfesor,Estudiante};use Illuminate\Database\QueryException;use Illuminate\Http\{JsonResponse,Request};use Illuminate\View\View;
class ScannerController extends Controller{public function index():View{return view('profesor.escanear',['clases'=>auth()->user()->clasesProfesor()->with(['materia','grado','seccion'])->get()]);}public function verificar(Request $request):JsonResponse{$d=$request->validate(['qr_token'=>['required','string'],'clase_profesor_id'=>['required','integer']]);$e=Estudiante::where('qr_token',$d['qr_token'])->first();if(!$e)return response()->json(['message'=>'Código QR no válido.'],404);$c=ClaseProfesor::whereKey($d['clase_profesor_id'])->where('profesor_id',auth()->id())->first();if(!$c)return response()->json(['message'=>'La clase no pertenece al profesor autenticado.'],403);if($e->grado_id!==$c->grado_id||$e->seccion_id!==$c->seccion_id)return response()->json(['message'=>'El estudiante no pertenece a esta clase.'],422);try{$a=Asistencia::create(['estudiante_id'=>$e->id,'clase_profesor_id'=>$c->id,'fecha'=>now()->toDateString(),'hora'=>now()->format('H:i:s'),'estado'=>'presente','metodo'=>'qr']);}catch(QueryException $x){if(in_array($x->getCode(),['23000','23505'],true))return response()->json(['message'=>'La asistencia ya fue registrada hoy para esta clase.'],409);throw $x;}return response()->json(['message'=>'Asistencia registrada correctamente.','asistencia'=>$a->load('estudiante.user')],201);}}
